```python
#!/usr/bin/env python3
import csv, json, sys, tempfile, os

def totals(path):
    count = 0
    total = 0.0
    with open(path, newline='', encoding='utf-8') as f:
        for row in csv.DictReader(f):
            oid = (row.get('order_id') or '').strip()
            raw = (row.get('total') or '').strip()
            if not oid and not raw:
                continue
            if not oid or not raw:
                raise ValueError('Every nonblank row needs order_id and total')
            total += float(raw)
            count += 1
    return {'count': count, 'sum': total}

def write_json(path, data):
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2)
        f.write('\n')

def selftest():
    with tempfile.TemporaryDirectory() as d:
        src = os.path.join(d, 'orders.csv')
        out = os.path.join(d, 'totals.json')
        with open(src, 'w', newline='', encoding='utf-8') as f:
            f.write('order_id,total\nA1,10.50\nA2,4.25\n\nA3,0\n')
        write_json(out, totals(src))
        with open(out, encoding='utf-8') as f:
            assert json.load(f) == {'count': 3, 'sum': 14.75}

def main():
    if len(sys.argv) != 3:
        raise SystemExit('usage: python orders_to_json.py orders.csv totals.json')
    write_json(sys.argv[2], totals(sys.argv[1]))

if __name__ == '__main__':
    selftest()
    main()
```
Run: `python orders_to_json.py orders.csv totals.json`
